import parse

# Test R2: digit field numbering in format spec
# Like {0:d} or {1:d}
try:
    r = parse.parse('{0:d} {1:d}', '12 34')
    print('R2 test {0:d}:', r)
except Exception as e:
    print('R2 test error:', e)

try:
    r = parse.parse('{:d} {:d}', '12 34')
    print('R2 test without numbers:', r)
except Exception as e:
    print('R2 test error:', e)

# The doc says: 'Numbered fields are also not supported'
# But what if someone uses {0:d}? Let's see...
try:
    r = parse.parse('{0:d}', '12')
    print('R2 test {0:d}:', r)
except Exception as e:
    print('R2 test error:', e)

# What about {1:d}?
try:
    r = parse.parse('{1:d}', '12')
    print('R2 test {1:d}:', r)
except Exception as e:
    print('R2 test error:', e)
"
